  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "SEL_ARR_0_0_1_0_1_0_0_0_0_0_1_1_0_0_1_1_0_0_1__ETC___d195", 192u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "SEL_ARR_0_0_1_0_1_0_0_0_0_0_1_1_0_0_1_1_0_0_1__ETC___d210", 224u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "SEL_ARR_0_0_1_0_1_0_0_0_0_0_1_1_0_0_1_1_0_0_1__ETC___d225", 256u);
